python3 -c import os,json
r=[]; unresolved=[]; root='/WORK/liwei_work/jcwu/ORCHIDEE-MAN-JAX'
uid=os.getuid()
for name in os.listdir('/proc'):
 if not name.isdigit(): continue
 p='/proc/'+name
 try:
  if os.stat(p).st_uid!=uid: continue
  cmd=open(p+'/cmdline','rb').read().replace(b'\0',b' ').decode('utf-8','replace')
  try: cwd=os.readlink(p+'/cwd')
  except Exception as e: cwd='UNREADABLE'; unresolved.append({'pid':name,'cmd':cmd,'error':str(e)})
  try: env=open(p+'/environ','rb').read().decode('utf-8','replace')
  except Exception: env=''
  if root in cmd or root in cwd or root in env: r.append({'pid':name,'cmd':cmd,'cwd':cwd,'environment_mentions_project':root in env})
 except (FileNotFoundError,ProcessLookupError): pass
 except Exception as e: unresolved.append({'pid':name,'error':str(e)})
print(json.dumps({'project_processes':r,'unreadable_processes':unresolved}))
